//! 🎭️ Both actual guest export families borrow one paid original actor context and retain failed outputs.
use super::*;
use crate::component::wasip2::exports::semio::framework::reactor as Wire;
use semio_framework::kernel;
use std::cell::RefCell;

crate::component_persistent_local!{
 static ORIGINAL_ACTOR_ENTRY:RefCell<OriginalActorGuestEntry>=RefCell::new(OriginalActorGuestEntry::new());
 static ORIGINAL_ACTOR_RECEIPT:RefCell<OriginalActorFixedReceipt>=RefCell::new(OriginalActorFixedReceipt::empty());
 static ORIGINAL_WIT_OUTPUT:RefCell<ManuallyDrop<Option<Wire::TurnResult>>>=RefCell::new(ManuallyDrop::new(None));
 static ORIGINAL_OWNED_OUTPUT:RefCell<ManuallyDrop<Option<kernel::TurnResult>>>=RefCell::new(ManuallyDrop::new(None));
}
fn busy()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original actor export remains checked out")}
fn with_entry<T>(body:impl FnOnce(&mut OriginalActorGuestEntry)->T)->Result<T,ValueError>{ORIGINAL_ACTOR_ENTRY.with(|original|original.try_borrow_mut().map(|mut original|body(&mut original)).map_err(|_|busy()))}
fn step_budget(input:RetainedTurnInput,fuel:u64,deadline_ms:u32)->Result<StepBudget,ValueError>{let start=semio_framework_job::default_now_us().ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"original actor clock is unavailable"))?;StepBudget::from_duration(fuel,start,u64::from(deadline_ms)*1000,input.grant).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"original actor deadline overflows its supplied clock"))}
fn native_input(input:Wire::RetainedTurnInput)->Result<RetainedTurnInput,ValueError>{let extent=|value:u64|usize::try_from(value).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"original actor wire extent exceeds native address space"));let grant=input.grant;let original=RetainedTurnInput{operation:input.operation,generation:input.generation,epoch:input.epoch,grant:semio_framework_value::RetainedCloneGrant{maximum_items:extent(grant.maximum_items)?,maximum_copy_bytes:extent(grant.maximum_copy_bytes)?,maximum_capacity_bytes:extent(grant.maximum_capacity_bytes)?,maximum_release_bytes:extent(grant.maximum_release_bytes)?,maximum_depth:extent(grant.maximum_depth)?}};original.validate()?;Ok(original)}
fn progress(original:RetainedCloneProgress)->Wire::RetainedProgress{Wire::RetainedProgress{copied_items:original.copied_items as u64,copied_bytes:original.copied_bytes as u64,retained_capacity_bytes:original.retained_capacity_bytes as u64,released_bytes:original.released_bytes as u64}}
fn kind(original:ValueRefusalKind)->Wire::ActorAuthorityRefusal{match original{ValueRefusalKind::InvalidValue=>Wire::ActorAuthorityRefusal::InvalidValue,ValueRefusalKind::Canceled=>Wire::ActorAuthorityRefusal::Canceled,ValueRefusalKind::OwnershipLimit=>Wire::ActorAuthorityRefusal::OwnershipLimit,ValueRefusalKind::AllocationFailed=>Wire::ActorAuthorityRefusal::AllocationFailed,ValueRefusalKind::WorkLimit=>Wire::ActorAuthorityRefusal::WorkLimit,ValueRefusalKind::DepthLimit=>Wire::ActorAuthorityRefusal::DepthLimit,ValueRefusalKind::UnsupportedOwner=>Wire::ActorAuthorityRefusal::UnsupportedOwner,ValueRefusalKind::InvariantViolated=>Wire::ActorAuthorityRefusal::InvariantViolated}}
fn failure(input:Wire::RetainedTurnInput,spent:RetainedCloneProgress,authority:Option<ValueRefusalKind>)->Wire::ActorCallRefusal{Wire::ActorCallRefusal{input,spent:progress(spent),failure:authority.map(|original|Wire::ActorCallFailure::Authority(kind(original))).unwrap_or(Wire::ActorCallFailure::Semantic)}}
fn outputs_held()->bool{ORIGINAL_WIT_OUTPUT.with(|output|output.borrow().is_some())||ORIGINAL_OWNED_OUTPUT.with(|output|output.borrow().is_some())}
/// 🌱️ Empty admission cannot receive or consume the original Host event batch.
pub fn admit_wit(input:Wire::RetainedTurnInput)->Wire::ActorAdmissionCall{let original=(||{let native=native_input(input)?;with_entry(|entry|OriginalActorAdmissionReply::borrow_original(&entry.admit_step(native)))})();match original{Ok(reply)=>Wire::ActorAdmissionCall{input,spent:progress(reply.spent),ready:reply.ready,refusal:reply.refusal.map(kind)},Err(error)=>Wire::ActorAdmissionCall{input,spent:progress(error.retained_progress()),ready:false,refusal:Some(kind(error.kind))}}}
/// ♻️ Refused semantic outputs remain in original custody until their actual retirement producer exists.
pub fn close_wit(input:Wire::RetainedTurnInput)->Wire::ActorContextCloseCall{if outputs_held(){return Wire::ActorContextCloseCall{input,spent:progress(Default::default()),complete:false,blocked:true,refusal:None}}let original=(||{let native=native_input(input)?;with_entry(|entry|OriginalActorCloseReply::borrow_original(&entry.close_step(native)))})();match original{Ok(reply)=>Wire::ActorContextCloseCall{input,spent:progress(reply.spent),complete:reply.complete,blocked:reply.blocked,refusal:reply.refusal.map(kind)},Err(error)=>Wire::ActorContextCloseCall{input,spent:progress(error.retained_progress()),complete:false,blocked:false,refusal:Some(kind(error.kind))}}}
/// 🤝️ A successful reservation releases the same output; every authority refusal retains it.
pub fn poll_wit<PA:crate::app::PluginApp+'static>(runtime:&crate::plugin_runtime::PluginRuntime<PA>,events:Vec<Wire::Event>,budget:Wire::Budget)->Result<Wire::TurnResult,Wire::ActorCallRefusal>{
 let input=budget.retained;let mut spent=Default::default();let mut semantic=false;
 let admitted=crate::operation_authority::with_actor_operation_authority(|identity|{let native=native_input(input)?;let step=step_budget(native,budget.fuel,budget.deadline_ms)?;if outputs_held(){return Err(busy())}let call=with_entry(|entry|entry.dispatch_step(native,step,&mut spent,semio_framework_job::default_now_us,|cx|crate::plugin_runtime::drive_self_waking_ready(crate::reactor::poll(runtime,events,budget,identity,cx))))?;spent=call.receipt_spent;match call.result{Ok(output)=>{ORIGINAL_WIT_OUTPUT.with(|pending|**pending.borrow_mut()=Some(output));call.input.return_original(spent)?;ORIGINAL_WIT_OUTPUT.with(|pending|{let pending=pending.borrow();let output=pending.as_ref().unwrap();crate::operation_authority::return_walk::walk_turn(output,&mut |kind,count|{let code=crate::component::wasip2::semio::framework::pure::operation_reserve_return(kind,count as u64);if code==0{Ok(())}else{Err(crate::operation_authority::refusal(code))}})})},Err(OriginalActorEntryFailure::Authority(error))=>Err(error),Err(OriginalActorEntryFailure::Semantic)=>{semantic=true;Ok(())}}});
 match admitted{Err(error)=>Err(failure(input,spent,Some(error.kind))),Ok(())if semantic=>Err(failure(input,spent,None)),Ok(())=>ORIGINAL_WIT_OUTPUT.with(|pending|pending.borrow_mut().take().ok_or_else(||failure(input,spent,Some(ValueRefusalKind::InvariantViolated))))}
}
pub fn admit_owned(input:RetainedTurnInput)->u64{let reply=with_entry(|entry|OriginalActorAdmissionReply::borrow_original(&entry.admit_step(input))).unwrap_or_else(|error|OriginalActorAdmissionReply{input,spent:error.retained_progress(),ready:false,refusal:Some(error.kind)});return_fixed(OriginalActorFixedCall{input,spent:reply.spent,kind:OriginalActorFixedKind::Admission{ready:reply.ready,refusal:reply.refusal}})}
pub fn close_owned(input:RetainedTurnInput)->u64{if outputs_held(){return return_fixed(OriginalActorFixedCall{input,spent:Default::default(),kind:OriginalActorFixedKind::Close{complete:false,blocked:true,refusal:None}})}let reply=with_entry(|entry|OriginalActorCloseReply::borrow_original(&entry.close_step(input))).unwrap_or_else(|error|OriginalActorCloseReply{input,spent:error.retained_progress(),complete:false,blocked:false,refusal:Some(error.kind)});return_fixed(OriginalActorFixedCall{input,spent:reply.spent,kind:OriginalActorFixedKind::Close{complete:reply.complete,blocked:reply.blocked,refusal:reply.refusal}})}
fn return_fixed(call:OriginalActorFixedCall)->u64{ORIGINAL_ACTOR_RECEIPT.with(|original|{let mut original=original.borrow_mut();original.write(call);u64::from(original.bytes().as_ptr()as usize as u32)|(104u64<<32)})}
/// 📤️ The original fixed result is resident instance storage, so deallocation releases only its loan.
pub fn fixed_receipt_pointer(pointer:u32,length:u32)->bool{length==104&&ORIGINAL_ACTOR_RECEIPT.with(|original|original.borrow().bytes().as_ptr()as usize as u32==pointer)}
pub fn poll_owned<PA:crate::app::PluginApp+'static>(runtime:&crate::plugin_runtime::PluginRuntime<PA>,input:crate::owned_abi::PollInput)->u64{
 let retained=input.budget.retained;let mut spent=Default::default();let mut semantic=false;
 let admitted=crate::operation_authority::with_actor_operation_authority(|identity|{let step=step_budget(retained,input.budget.fuel,input.budget.deadline_ms)?;if outputs_held(){return Err(busy())}let call=with_entry(|entry|entry.dispatch_step(retained,step,&mut spent,semio_framework_job::default_now_us,|cx|crate::plugin_runtime::drive_self_waking_ready(crate::reactor::poll_kernel(runtime,input.events,input.command_page,input.cold_pair_page,input.budget,identity,cx))))?;spent=call.receipt_spent;match call.result{Ok(output)=>{ORIGINAL_OWNED_OUTPUT.with(|pending|**pending.borrow_mut()=Some(output));call.input.return_original(spent)?;Ok(())},Err(OriginalActorEntryFailure::Authority(error))=>Err(error),Err(OriginalActorEntryFailure::Semantic)=>{semantic=true;Ok(())}}});
 match admitted{Err(error)=>return_fixed(OriginalActorFixedCall{input:retained,spent,kind:OriginalActorFixedKind::Failure{authority:Some(error.kind)}}),Ok(())if semantic=>return_fixed(OriginalActorFixedCall{input:retained,spent,kind:OriginalActorFixedKind::Failure{authority:None}}),Ok(())=>ORIGINAL_OWNED_OUTPUT.with(|pending|{let pending=pending.borrow();crate::owned_abi::return_json(&Ok::<_,()>(pending.as_ref().unwrap()))})}
}
